final class Downloader {
    func fetch(_ url: URL, onDone: @escaping (Result<Data, Error>) -> Void) {
        URLSession.shared.dataTask(with: url) { data, _, error in
            if let error { onDone(.failure(error)) }
            else { onDone(.success(data ?? Data())) }      // background queue
        }.resume()
    }

    func fetch(_ url: URL) async throws -> Data {           // modern form
        try await withCheckedThrowingContinuation { cont in
            fetch(url) { cont.resume(with: $0) }            // exactly one resume
        }
    }
}
